export function getAudioSource(slug: string, accent: "us" | "uk"): any | undefined {
  const entry = AUDIO_MAP[slug];
  if (!entry) return undefined;
  return accent === "uk" ? (entry.uk || entry.us) : (entry.us || entry.uk);
}
